"""`KK Eyebrows (mayuge)`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = 'KK Eyebrows (mayuge)'


def build(lib):
    t = lib.new_material(NAME, props={
            'surface_render_method': 'BLENDED',
            'blend_method': 'BLEND',
            'use_backface_culling': True,
            'use_backface_culling_lightprobe_volume': False,
            'preview_render_type': 'FLAT',
            'diffuse_color': (0.17857142, 0.17857142, 0.17857142, 1.0),
            'roughness': 1.0,
            'line_color': (0.0, 0.0, 0.0, 1.0),
        })

    t.node('NodeFrame', 'FrameInfo.001', props={
        'location': (-79.00003, 114.75),
        'width': 776.0,
        'height': 346.75003,
        'label': 'Shader',
        'use_custom_color': True,
        'color': (0.33001542, 0.4420454, 0.6247832),
        'label_size': 23,
    })
    t.node('NodeFrame', 'Frame.001', props={
        'location': (-355.0, 112.75),
        'width': 260.97662,
        'height': 192.75,
        'label': 'Texture files',
        'use_custom_color': True,
        'color': (0.2901505, 0.6787529, 0.1812863),
        'label_size': 23,
    })
    t.node('NodeFrame', 'FrameInfo.002', props={
        'location': (712.0, 112.75),
        'width': 200.0,
        'height': 149.75,
        'label': 'Output',
        'use_custom_color': True,
        'color': (0.6247832, 0.073067226, 0.042191483),
        'label_size': 23,
    })
    t.node('ShaderNodeGroup', 'combine', parent='FrameInfo.001', inputs={'Light colors': (0.504946, 0.347894, 0.311926, 1.0), 'Dark colors': (0.0, 0.0, 0.0, 1.0), 'Alpha mask': (1.0, 1.0, 1.0, 1.0), 'Alpha mask (alpha)': 1.0, 'Alpha mask (custom)': (1.0, 1.0, 1.0, 1.0), 'Force visibility': 0.0}, props={
        'node_tree': lib.group('.Combine colors'),
        'location': (346.14822, -43.51297),
        'width': 400.0,
    })
    t.node('ShaderNodeOutputMaterial', 'out', parent='FrameInfo.002', hide_inputs=('Volume', 'Displacement', 'Thickness'), props={
        'location': (29.690613, -43.854797),
    })
    t.node('ShaderNodeGroup', 'textures', parent='Frame.001', hide_outputs=('Kage texture', 'Kage texture (alpha)', 'Down texture', 'Down texture (alpha)'), props={
        'node_tree': lib.group('.Tex Face misc'),
        'location': (30.241089, -43.28595),
        'width': 200.97664,
    })
    t.node('ShaderNodeGroup', 'light', parent='FrameInfo.001', inputs={'Eyebrow color': (0.0, 0.0, 0.0, 1.0), 'Eyebrow color dark': (0.0, 0.0, 0.0, 1.0)}, props={
        'node_tree': lib.group('.KK Eyebrows'),
        'location': (29.647552, -45.86737),
        'width': 296.7656,
    })

    t.link('combine', 'Result', 'out', 'Surface')
    t.link('textures', 'Main texture (alpha)', 'combine', 'Main texture (alpha)')
    t.link('textures', 'Toon shading', 'combine', 'Toon shading')
    t.link('light', 'Light colors', 'combine', 'Light colors')
    t.link('textures', 'Main texture', 'light', 'Main texture')
    t.link('light', 'Dark colors', 'combine', 'Dark colors')
    return t
